        begin
            @(negedge pclk); psel = 1; penable = 0; pwrite = 1; paddr = a; pwdata = d;
            @(negedge pclk); penable = 1; #1 err = pslverr;
            @(negedge pclk); psel = 0; penable = 0; pwrite = 0;
