            if (active[i])
                irq_id = i;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mask <= 8'h00;
            mode <= 8'h00;
        end else if (we) begin
            case (addr)
                ADDR_MASK: mask <= wdata;
                ADDR_MODE: mode <= wdata;
                default:   ;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            src_q <= 8'h00;
        else
            src_q <= src;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            edge_pend <= 8'h00;
        end else begin
            for (j = 0; j < 8; j = j + 1) begin
                if (ack_vec[j])
                    edge_pend[j] <= 1'b0;
