        @(negedge clk); in_valid = 0;
        @(posedge clk); #1; expect_out(0, 8'h00);
        // single word held while the sink stalls
        @(negedge clk); out_ready = 0; in_valid = 1; in_data = 8'h5C;
        @(negedge clk); in_valid = 0;
        repeat (3) begin
            @(posedge clk); #1; expect_out(1, 8'h5C);
        end
        @(negedge clk); out_ready = 1;
        @(posedge clk); #1; expect_out(0, 8'h00);
