// ----------------------------------------------------------------------------
// token_bucket
//
// Token-bucket rate limiter. The bucket holds up to CAP tokens and starts full
// after reset. A refill timer adds one token every `rate` cycles (rate = 0
// disables refill). A request is granted when the bucket is not empty and each
// grant consumes one token. deny_cnt counts rejected requests (saturating).
//
// All outputs except `tokens` and `deny_cnt` are combinational.
// ----------------------------------------------------------------------------
module token_bucket #(
    parameter integer CAP = 4,          // bucket capacity (tokens), 1 <= CAP < 2**TW
    parameter integer TW  = 3,          // token counter width
    parameter integer RW  = 8           // refill period width
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire [RW-1:0] rate,          // refill period in cycles, 0 = refill disabled
    input  wire          req,           // request (one token per granted request)
    input  wire          clr_stats,     // synchronous clear of deny_cnt
    output wire          grant,
    output reg  [TW-1:0] tokens,
    output wire          empty,
    output wire          full,
    output wire          refill,
    output reg  [7:0]    deny_cnt
);
    localparam [TW-1:0] CAP_V = CAP;

    reg [RW-1:0] timer;
    reg [TW-1:0] tokens_nx;

    // ------------------------------------------------------------------
    // Refill timer: one token every `rate` cycles
    // ------------------------------------------------------------------
    assign refill = (timer == rate - 1'b1);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            timer <= {RW{1'b0}};
        else if (refill)
            timer <= {RW{1'b0}};
        else
            timer <= timer + 1'b1;
    end

    // ------------------------------------------------------------------
    // Grant / token accounting
    // ------------------------------------------------------------------
    assign empty = (tokens == {TW{1'b0}});
    assign full  = (tokens == CAP_V);
    assign grant = req && !empty;

    always @(*) begin
        tokens_nx = tokens;
        if (refill && tokens_nx != CAP_V)
            tokens_nx = tokens_nx + 1'b1;
        if (grant)
            tokens_nx = tokens_nx - 1'b1;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tokens <= CAP_V;
        else
            tokens <= tokens_nx;
    end

    // ------------------------------------------------------------------
    // Statistics: saturating count of denied requests
    // ------------------------------------------------------------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            deny_cnt <= 8'd0;
        else if (clr_stats)
            deny_cnt <= 8'd0;
        else if (req && !grant && deny_cnt != 8'hFF)
            deny_cnt <= deny_cnt + 8'd1;
    end
endmodule

`timescale 1ns/1ps
module tb;
    reg        clk = 0, rst_n = 1;
    reg  [7:0] rate = 8'd4;
    reg        req = 0, clr_stats = 0;
    wire       grant, empty, full, refill;
    wire [2:0] tokens;
    wire [7:0] deny_cnt;
    integer errors = 0, i;

    token_bucket dut (.clk(clk), .rst_n(rst_n), .rate(rate), .req(req), .clr_stats(clr_stats),
                      .grant(grant), .tokens(tokens), .empty(empty), .full(full), .refill(refill),
                      .deny_cnt(deny_cnt));
    always #5 clk = ~clk;
    initial begin #100000 $display("ERROR: watchdog timeout"); $finish; end

    // expected grant/tokens for 12 cycles of continuous requests at rate 4, starting full
    reg [11:0] exp_grant = 12'b0001_0001_1111;   // bit i = cycle i
    integer    exp_tok [0:11];

    initial begin
        exp_tok[0] = 4; exp_tok[1] = 3; exp_tok[2] = 2; exp_tok[3] = 1; exp_tok[4] = 1;
        exp_tok[5] = 0; exp_tok[6] = 0; exp_tok[7] = 0; exp_tok[8] = 1; exp_tok[9] = 0;
        exp_tok[10] = 0; exp_tok[11] = 0;
        #1 rst_n = 0;
        #2;
        if (tokens !== 3'd4 || full !== 1'b1 || empty !== 1'b0 || deny_cnt !== 8'd0) begin
            $display("FAIL: reset state tokens=%0d full=%b empty=%b", tokens, full, empty);
            errors = errors + 1;
        end
        @(negedge clk); rst_n = 1;
        // drain with continuous requests
        for (i = 0; i < 12; i = i + 1) begin
            req = 1; #1;
            if (tokens !== exp_tok[i] || grant !== exp_grant[i]) begin
                $display("FAIL: cycle %0d tokens=%0d grant=%b expected tokens=%0d grant=%b",
                         i, tokens, grant, exp_tok[i], exp_grant[i]);
                errors = errors + 1;
            end
            @(negedge clk);
        end
        req = 0;
        if (deny_cnt !== 8'd6) begin
            $display("FAIL: deny_cnt=%0d expected 6", deny_cnt); errors = errors + 1;
        end
        // idle: bucket refills to capacity and stays there
        repeat (30) @(negedge clk);
        if (tokens !== 3'd4 || full !== 1'b1) begin
            $display("FAIL: bucket not refilled, tokens=%0d", tokens); errors = errors + 1;
        end
        // clear statistics
        clr_stats = 1; @(negedge clk); clr_stats = 0;
        if (deny_cnt !== 8'd0) begin
            $display("FAIL: deny_cnt not cleared (%0d)", deny_cnt); errors = errors + 1;
        end
        if (errors == 0) $display("TEST PASSED");
        else $display("TEST FAILED: %0d errors", errors);
        $finish;
    end
endmodule

