steps.detail:
// Byte-to-word packer: collects 8-bit input beats into 32-bit little-endian output words.
// A beat flagged with in_last closes the current word early (zero padded, out_keep marks
// the valid bytes). Both interfaces use valid/ready handshakes.
module width_packer (
    input  wire        clk,
    input  wire        rst_n,
    // byte input
    input  wire        in_valid,
    output wire        in_ready,
    input  wire [7:0]  in_data,
    input  wire        in_last,
    // word output
    output reg         out_valid,
    input  wire        out_ready,
    output reg  [31:0] out_data,
    output reg  [3:0]  out_keep,
    output reg         out_last
);
    reg [23:0] acc;      // bytes 0..2 of the word being assembled
    reg [1:0]  count;    // bytes held in acc
    reg [31:0] word;
    reg [3:0]  keep;

    wire pop      = out_valid && out_ready;
    wire out_free = !out_valid || out_ready;
    wire full     = (count == 2'd3);
    wire closes   = full || in_last;

    // Input stalls only while the output register is occupied and cannot drain
    assign in_ready = out_free || !full;

    wire accept   = in_valid && in_ready;
    wire complete = accept && closes;

    // Word formed by the held bytes plus the incoming byte
    always @(*) begin
        case (count)
            2'd0:    begin word = {24'd0, in_data};            keep = 4'b0001; end
            2'd1:    begin word = {16'd0, in_data, acc[7:0]};  keep = 4'b0011; end
            2'd2:    begin word = {8'd0, in_data, acc[15:0]};  keep = 4'b0111; end
            default: begin word = {in_data, acc[23:0]};        keep = 4'b1111; end
        endcase
    end

    // Output register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_valid <= 1'b0;
            out_data  <= 32'd0;
            out_keep  <= 4'd0;
            out_last  <= 1'b0;
        end else if (pop) begin
            out_valid <= 1'b0;
        end else if (complete) begin
            out_valid <= 1'b1;
            out_data  <= word;
            out_keep  <= keep;
            out_last  <= in_last;
        end
    end

    // Accumulator
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            acc   <= 24'd0;
            count <= 2'd0;
        end else if (accept) begin
            if (complete) begin
                count <= 2'd0;
            end else begin
                count <= count + 2'd1;
                case (count)
                    2'd0:    acc[7:0]   <= in_data;
                    2'd1:    acc[15:8]  <= in_data;
                    default: acc[23:16] <= in_data;
                endcase
            end
        end
    end
endmodule

`timescale 1ns/1ps
module tb;
    reg clk = 0, rst_n = 1;
    reg in_valid = 0, in_last = 0, out_ready = 1;
    reg [7:0] in_data = 0;
    wire in_ready, out_valid, out_last;
    wire [31:0] out_data;
    wire [3:0] out_keep;
    integer errors = 0, i, nw = 0;
    reg [31:0] got_d [0:31];
    reg [3:0]  got_k [0:31];
    reg        got_l [0:31];

    width_packer dut (.clk(clk), .rst_n(rst_n), .in_valid(in_valid), .in_ready(in_ready),
                      .in_data(in_data), .in_last(in_last), .out_valid(out_valid),
                      .out_ready(out_ready), .out_data(out_data), .out_keep(out_keep),
                      .out_last(out_last));
    always #5 clk = ~clk;
    initial begin #100000 $display("ERROR: watchdog timeout"); $finish; end

    // collect delivered words
    always @(posedge clk)
        if (out_valid && out_ready) begin
            got_d[nw] <= out_data; got_k[nw] <= out_keep; got_l[nw] <= out_last; nw <= nw + 1;
        end

    // send one byte, waiting for in_ready
    task send(input [7:0] d, input l);
        begin
            @(negedge clk); in_valid = 1; in_data = d; in_last = l;
            #1; while (in_ready !== 1'b1) begin @(negedge clk); #1; end
            @(posedge clk); #1; in_valid = 0; in_last = 0;
        end
    endtask

    task expect_word(input integer n, input [31:0] d, input [3:0] k, input l);
        if (got_d[n] !== d || got_k[n] !== k || got_l[n] !== l) begin
            $display("FAIL: word %0d = %h keep=%b last=%b, expected %h keep=%b last=%b",
                     n, got_d[n], got_k[n], got_l[n], d, k, l);
            errors = errors + 1;
        end
    endtask

    initial begin
        #1 rst_n = 0;
        #11 rst_n = 1;
        // 8-byte packet: two full words
        for (i = 0; i < 8; i = i + 1) send(8'h10 + i, i == 7);
        // 3-byte packet: partial word
        for (i = 0; i < 3; i = i + 1) send(8'hA0 + i, i == 2);
        // 6-byte packet
        for (i = 0; i < 6; i = i + 1) send(8'hC0 + i, i == 5);
        // 12-byte packet with the sink stalled at the start
        repeat (2) @(negedge clk);
        out_ready = 0;
        for (i = 0; i < 6; i = i + 1) send(8'h50 + i, 1'b0);
        @(negedge clk); out_ready = 1;
        for (i = 6; i < 12; i = i + 1) send(8'h50 + i, i == 11);
        repeat (4) @(negedge clk);
        if (nw != 8) begin $display("FAIL: %0d words delivered, expected 8", nw); errors = errors + 1; end
        expect_word(0, 32'h13121110, 4'b1111, 1'b0);
        expect_word(1, 32'h17161514, 4'b1111, 1'b1);
        expect_word(2, 32'h00A2A1A0, 4'b0111, 1'b1);
        expect_word(3, 32'hC3C2C1C0, 4'b1111, 1'b0);
        expect_word(4, 32'h0000C5C4, 4'b0011, 1'b1);
        expect_word(5, 32'h53525150, 4'b1111, 1'b0);
        expect_word(6, 32'h57565554, 4'b1111, 1'b0);
        expect_word(7, 32'h5B5A5958, 4'b1111, 1'b1);
        if (errors == 0) $display("TEST PASSED");
        else $display("TEST FAILED: %0d errors", errors);
        $finish;
    end
endmodule

