module tb_exhaustive_scratch;
    reg [12:0] cw;
    wire [7:0] data;
    wire single_err, double_err;
    wire [3:0] err_pos;
    integer i, errors;

    hamming_secded dut(.cw(cw), .data(data), .single_err(single_err),
                        .double_err(double_err), .err_pos(err_pos));

    function [3:0] synf(input [12:0] c);
        integer j, b;
        reg [3:0] s;
        begin
            s = 0;
            for (j = 1; j <= 12; j = j + 1)
                for (b = 0; b < 4; b = b + 1)
                    if ((j >> b) & 1) s[b] = s[b] ^ c[j];
            synf = s;
        end
    endfunction

    function [7:0] rawf(input [12:0] c);
        rawf = {c[12], c[11], c[10], c[9], c[7], c[6], c[5], c[3]};
    endfunction

    reg [3:0] syn_e;
    reg parity_e;
    reg [7:0] exp_data;
    reg exp_single, exp_double;
    reg [3:0] exp_errpos;

    initial begin
        errors = 0;
        for (i = 0; i < 8192; i = i + 1) begin
            cw = i;
            #1;
            syn_e = synf(cw);
            parity_e = ^cw;
            if (syn_e == 0 && parity_e == 0) begin
                exp_single = 0; exp_double = 0; exp_errpos = 0; exp_data = rawf(cw);
            end else if (parity_e == 1 && syn_e >= 1 && syn_e <= 12) begin
                exp_single = 1; exp_double = 0; exp_errpos = syn_e;
                exp_data = rawf(cw);
                case (syn_e)
                    4'd3: exp_data[0] = ~exp_data[0];
                    4'd5: exp_data[1] = ~exp_data[1];
                    4'd6: exp_data[2] = ~exp_data[2];
                    4'd7: exp_data[3] = ~exp_data[3];
                    4'd9: exp_data[4] = ~exp_data[4];
                    4'd10: exp_data[5] = ~exp_data[5];
                    4'd11: exp_data[6] = ~exp_data[6];
                    4'd12: exp_data[7] = ~exp_data[7];
                    default: ;
                endcase
            end else if (parity_e == 1 && syn_e == 0) begin
                exp_single = 1; exp_double = 0; exp_errpos = 0; exp_data = rawf(cw);
            end else if (parity_e == 1 && syn_e >= 13) begin
                exp_single = 0; exp_double = 1; exp_errpos = 0; exp_data = rawf(cw);
            end else begin // parity_e==0 && syn_e != 0
                exp_single = 0; exp_double = 1; exp_errpos = 0; exp_data = rawf(cw);
            end

            if (data !== exp_data || single_err !== exp_single ||
                double_err !== exp_double || err_pos !== exp_errpos) begin
                errors = errors + 1;
                if (errors <= 10)
                    $display("MISMATCH cw=%h: got data=%h single=%b double=%b errpos=%h exp data=%h single=%b double=%b errpos=%h",
                              cw, data, single_err, double_err, err_pos,
                              exp_data, exp_single, exp_double, exp_errpos);
            end
        end
        if (errors == 0) $display("EXHAUSTIVE: ALL 8192 CASES MATCH SPEC");
        else $display("EXHAUSTIVE: %0d MISMATCHES", errors);
        $finish;
    end
