            timer <= {RW{1'b0}};
        else
            timer <= timer + 1'b1;
    end
+++ new
    assign refill = (rate != {RW{1'b0}}) && (timer >= rate - 1'b1);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            timer <= {RW{1'b0}};
        else if (rate == {RW{1'b0}})
            timer <= {RW{1'b0}};
        else if (refill)
            timer <= {RW{1'b0}};
        else
            timer <= timer + 1'b1;
